s1=B/'vnm-s1-economic-returns/2026-11-13/S1_ECONOMIC_RETURNS.json';w=B/'vnm-s1-wacc-q3/2026-11-13/WACC_ROIC_Q3_ASSESSMENT.json';s2=B/'vnm-s2-public-disclosure/2026-11-13/S2_CLOSURE_ACCEPTANCE.json';six=B/'vnm-final-scoring-closure/2026-11-11/six-rubrics.json';step1=B/'vnm-formal-scoring-step1/2026-11-13/VNM_ASSESSMENT_CANDIDATES.json'
