write('VNM_4_RUBRIC_RESOLUTION.json',{'contract':'vnm-step4-four-rubric-resolution-v1','ticker':'VNM','cutoff':'2026-10-30','rows':four,'calculations':{'multiYearScenarioDiagnostics':spans,'epsSeries':eps,'nominalEpsCagr':str(nominal),'nominalLatestGrowth':str(latest),'bookPlusCashPerShareChangeDiagnostic':str(bookCash),'bookPlusCashIsIntrinsicReturn':False,'allocationBridge':allocation,'s2CoreCases':len(L['coreScenarios']),'s2MinimumCoreSurplusVnd':L['coreMinimumSurplusVnd'],'s2SupplementalSensitivityMinimumVnd':L['additionalSensitivityMinimumSurplusVnd'],'s2Closed':L['status']=='CLOSED'},'FACT':'Native common earnings, share counts, JV movement and distributions retain source identity/period/scope. No new fact admission.','ESTIMATE':'Normalized NOPAT/capital and scenario ranges retain S1 assumptions.','ASSUMPTION':'S5 forecasts are forward scenarios, never historical realized allocation outcomes.','researchClosuresUnchanged':True})
