 row['fiveDimensionConfidenceReference']='VNM_M1_RISK_GATE_VALIDATION.json#/confidence'
 for topic in row['topicAssessments']:
  topic['confidence']=row['confidence'];topic['fiveDimensionConfidenceReference']=row['fiveDimensionConfidenceReference'];topic['decisionCutoff']='2026-10-30';topic['knowledgeTime']=read(O/'RUN_CONTEXT.json')['knownAt'];topic['classification']='ANALYST_JUDGMENT_SUPPORTED_BY_RETAINED_FACTS_AND_ESTIMATES';topic['invalidationConditions']=row['invalidationConditions'];topic['authorization']='PENDING_NOT_HUMAN_ADOPTED'
 row['decisionCutoff']='2026-10-30';row['knowledgeTime']=read(O/'RUN_CONTEXT.json')['knownAt']
